import pandas as pd

def run(inputs: dict) -> dict:
    events = inputs["app_events"].copy()

    events = events.sort_values(["user_id", "event_ts", "event_id"], kind="mergesort")

    activity_types = {"view", "click", "logout"}
    threshold = pd.Timedelta(minutes=30)

    result_rows = []

    for user_id, grp in events.groupby("user_id", sort=False):
        session_num = 0
        cur = None  # dict holding current open session state

        def flush(cur):
            result_rows.append({
                "user_id": user_id,
                "session_num": cur["session_num"],
                "session_start": cur["session_start"],
                "session_end": cur["last_activity"],
                "event_count": cur["event_count"],
                "heartbeat_count": cur["heartbeat_count"],
            })

        for row in grp.itertuples(index=False):
            ts = row.event_ts
            etype = row.event_type

            if etype in activity_types:
                starts_new = False
                if cur is None:
                    starts_new = True
                else:
                    if ts - cur["last_activity"] > threshold:
                        starts_new = True

                if starts_new:
                    if cur is not None:
                        flush(cur)
                    session_num += 1
                    cur = {
                        "session_num": session_num,
                        "session_start": ts,
                        "last_activity": ts,
                        "event_count": 1,
                        "heartbeat_count": 0,
                    }
                else:
                    cur["last_activity"] = ts
                    cur["event_count"] += 1

                if etype == "logout":
                    flush(cur)
                    cur = None

            else:  # heartbeat
                if cur is not None and (ts - cur["last_activity"]) <= threshold:
                    cur["event_count"] += 1
                    cur["heartbeat_count"] += 1
                # else dropped

        if cur is not None:
            flush(cur)

    columns = ["user_id", "session_num", "session_start", "session_end",
               "event_count", "heartbeat_count"]

    if result_rows:
        out = pd.DataFrame(result_rows, columns=columns)
    else:
        out = pd.DataFrame(columns=columns)

    out["user_id"] = out["user_id"].astype("int64") if len(out) else out["user_id"]
    out["session_num"] = out["session_num"].astype("int64") if len(out) else out["session_num"]
    out["event_count"] = out["event_count"].astype("int64") if len(out) else out["event_count"]
    out["heartbeat_count"] = out["heartbeat_count"].astype("int64") if len(out) else out["heartbeat_count"]

    return {"user_sessions": out}
